#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Tuning knob: choose whether the sample dimension 'k' is the innermost
	// (contiguous) dimension in `data`.
	// For covariance, we reduce over 'k' very heavily, so having 'k' contiguous
	// improves cache behavior and vectorization of those reductions.
	static constexpr bool k_inner_contiguous = true;

	static constexpr auto make_data_layout() {
		if constexpr (k_inner_contiguous) {
			// data: logical shape k x j (N samples, M features)
			// Physical layout: j (features) outer, k (samples) inner
			//   scalar<num_t> ^ vector<'k'>() ^ vector<'j'>()
			// so each feature column j is stored as a contiguous vector over k.
			return k_vec ^ j_vec;
		} else {
			// Original layout:
			//   scalar<num_t> ^ vector<'j'>() ^ vector<'k'>()
			// i.e. each sample k stored as a contiguous row over j.
			return j_vec ^ k_vec;
		}
	}

	// data: k x j  (N samples, M features)
	DEFINE_PROTO_STRUCT(data_layout, make_data_layout());
	// cov:  i x j  (M x M) – rows i, columns j, with j the inner (contiguous) dim
	DEFINE_PROTO_STRUCT(cov_layout, j_vec ^ i_vec);
	// mean: j      (M)
	DEFINE_PROTO_STRUCT(mean_layout, j_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	// data: k x j  (k ~ N, j ~ M)
	using namespace noarr;

	// float_n = N (number of samples)
	float_n = (num_t)(data | get_length<'k'>());

	auto m_len = data | get_length<'j'>();

	// Iterate feature-major (outer 'j', inner 'k'). With the tuned layout
	// (k as innermost) this walks 'k' contiguously in the inner loop, which
	// is cache- and SIMD-friendly. For the fallback layout it is still
	// functionally correct, just with different locality characteristics.
	traverser(data).template for_dims<'j'>([=](auto tj) {
		tj.template for_each<'k'>([=](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			data[state] =
				static_cast<num_t>(k * j) / static_cast<num_t>(m_len);
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// Precompute reciprocals once – this saves divisions in the hot loops and
	// makes it easier for the compiler to keep them in registers.
	const num_t inv_float_n = num_t(1) / float_n;
	const num_t norm = num_t(1) / (float_n - num_t(1));

#pragma scop
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//
	// We traverse feature-major (outer 'j', inner 'k'). With 'k' contiguous
	// this becomes a reduction over a contiguous vector, which is very
	// amenable to auto-vectorization.
	traverser(data, mean).template for_dims<'j'>([=](auto tj) {
		// Accumulate into a local scalar so the reduction stays in a register.
		num_t sum = (num_t)0;

		tj.template for_each<'k'>([&](auto state) {
			sum += data[state];
		});

		mean[tj] = sum * inv_float_n;
	});

	// 2) data[k][j] -= mean[j]
	//
	// Again use feature-major traversal so we walk over the contiguous 'k'
	// dimension in the inner loop. We load mean[j] once per feature and keep
	// it in a register during the inner traversal.
	traverser(data, mean).template for_dims<'j'>([=](auto tj) {
		const num_t mean_j = mean[tj];

		tj.template for_each<'k'>([=](auto state) {
			data[state] -= mean_j;
		});
	});

	// 3) covariance
	//    for i in 0..M-1
	//      for j in i..M-1
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//        cov[j][i] = cov[i][j]
	//
	// Here we keep the logical loop order (i, j, then k) but:
	//  - use a local accumulator for the k-reduction (avoids repeated memory
	//    traffic for cov[i][j]),
	//  - rely on 'k' being the innermost/contiguous dimension so the inner
	//    loop is a dot product of two contiguous vectors over k.
	traverser(cov, data, data_i).template for_dims<'i'>([=](auto ti) {
		ti.template for_dims<'j'>([=](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// enforce j >= i (upper triangle, including diagonal)
			if (j_idx < i_idx)
				return;

			// Accumulate covariance contribution over all samples k in a
			// register.
			num_t sum = (num_t)0;

			tij.template for_each<'k'>([&](auto sk) {
				sum += data[sk] * data_i[sk];
			});

			const num_t value = sum * norm;

			// Store upper triangle element
			cov[s_ij] = value;

			// symmetry: cov[j][i] = cov[i][j]; avoid redundant store on diagonal
			if (j_idx != i_idx) {
				auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ji] = value;
			}
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'k'>(n) ^ // samples
		noarr::set_length<'i'>(m) ^ // cov rows
		noarr::set_length<'j'>(m);  // features / cov cols

	// allocate bags
	auto data = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto cov  = noarr::bag(noarr::scalar<num_t>() ^ tuning.cov_layout  ^ set_lengths);
	auto mean = noarr::bag(noarr::scalar<num_t>() ^ tuning.mean_layout ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_covariance(float_n, data.get_ref(), cov.get_ref(), mean.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results to stderr (to prevent DCE in benchmarking harnesses)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, cov.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
