// computation kernel
//
// Optimized for:
//   - row-major sweeps over `data` (k outer, j inner) to improve cache locality
//   - covariance accumulation using an outer-product formulation
//     (k outer, then i and j), which visits each sample row once and reuses it
//     from cache when updating the whole covariance row/column.
//
// Semantics are preserved exactly w.r.t. the original code:
//   - `mean[j]` is accumulated in the same k-order for each j
//   - data is centered (data[k][j] -= mean[j])
//   - covariance entries cov[i][j] accumulate k in increasing order,
//     then are divided by (float_n - 1), and symmetry cov[j][i] = cov[i][j]
//     is enforced afterwards.
//
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Column means
	//    mean[j] = (1/n) * sum_k data[k][j]
	// ---------------------------------------------------------------------

	// 1a) initialize means to zero
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = (num_t)0;
	});

	// 1b) accumulate means in a row-major traversal:
	//     k outer, j inner. For a fixed j, the sequence of additions is
	//     still k = 0..N-1, so the floating-point accumulation order for
	//     each mean[j] matches the original code.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		// tk: 'k' fixed, iterate remaining dim 'j'
		tk.for_each([&](auto s_kj) {
			mean[s_kj] += data[s_kj];
		});
	});

	// 1c) normalize means by number of samples
	traverser(mean).for_each([&](auto sj) {
		mean[sj] /= float_n;
	});

	// ---------------------------------------------------------------------
	// 2) Center the data: data[k][j] -= mean[j]
	//    Traverse row-major to write `data` contiguously.
	// ---------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto s_kj) {
			data[s_kj] -= mean[s_kj];
		});
	});

