	// 3) Covariance
	//
	//    We use an outer-product formulation:
	//      for k in 0..N-1:
	//        let x = centered row k (length M)
	//        for i in 0..M-1:
	//          for j in i..M-1:
	//            cov[i][j] += x[i] * x[j]
	//
