	//    over k (0..N-1) while improving data locality: each centered
	//    sample row is read sequentially and reused from cache when
	//    updating the whole covariance row.
	// ---------------------------------------------------------------------

	// 3a) Zero-initialize the covariance matrix (full M x M).
	traverser(cov).for_each([&](auto s_ij) {
		cov[s_ij] = (num_t)0;
	});

	// 3b) Accumulate the upper triangle using k-outer loops.
	traverser(cov, data, data_i).template for_dims<'k'>([&](auto tk) {
		// tk: traverser with fixed sample index 'k', remaining dims 'i' and 'j'

		// Loop over row index i (covariance row); 'i' is a feature index via data_i.
		tk.template for_dims<'i'>([&](auto tki) {
			// tki: 'k' and 'i' fixed, remaining dim 'j'
			auto si = tki.state(); // contains 'k' and 'i'
			auto i_idx = get_index<'i'>(si);

			// centered value of feature i for this sample k
			num_t x_ki = data_i[si];

			// iterate all columns j, updating only j >= i (upper triangle)
			tki.for_each([&](auto s_ijk) {
				auto j_idx = get_index<'j'>(s_ijk);
				if (j_idx < i_idx)
					return; // skip lower triangle; it will be filled by symmetry later

				// cov[i][j] += x_ki * data[k][j]
				cov[s_ijk] += x_ki * data[s_ijk];
			});
		});
	});

	// 3c) Normalize by (float_n - 1) and enforce symmetry:
	//     cov[i][j] /= (n - 1) for j >= i, then cov[j][i] = cov[i][j].
	traverser(cov).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// work only on upper triangle (including diagonal)
			if (j_idx < i_idx)
				return;

			// normalize
			cov[s_ij] /= (float_n - (num_t)1.0);

			// symmetry: cov[j][i] = cov[i][j]
			auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
			cov[s_ji] = cov[s_ij];
		});
	});
#pragma endscop
