#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/traverser_iter.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

/**
 * Tuning and layout configuration.
 *
 * We choose the physical layout of `data` so that the sample dimension 'k'
 * is innermost and therefore contiguous in memory. This improves cache and
 * prefetch behaviour for all loops where we iterate over samples.
 */
struct tuning_t {
	// Tuning knobs – can be adjusted per-architecture if needed.
	// They control when OpenMP parallel regions are actually spawned.
	static constexpr std::size_t mean_parallel_threshold   = 64; // min #features for parallel mean
	static constexpr std::size_t center_parallel_threshold = 64; // min #features for centering
	static constexpr std::size_t cov_parallel_threshold    = 16; // min #rows for parallel covariance

	// data: j x k  (M features, N samples)
	// Physically: scalar<num_t> ^ k_vec ^ j_vec => dimensions ('j','k')
	// -> 'k' is the innermost dimension => samples for a fixed feature j are contiguous
	DEFINE_PROTO_STRUCT(data_layout, k_vec ^ j_vec);

	// cov:  i x j  (M x M), row-major with 'j' as the innermost dimension
	DEFINE_PROTO_STRUCT(cov_layout, j_vec ^ i_vec);

	// mean: j      (M)
	DEFINE_PROTO_STRUCT(mean_layout, j_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	// data: j x k  (M features, N samples); we still conceptually think in terms of k (samples) and j (features)
	using namespace noarr;

	// float_n = N (number of samples)
	float_n = static_cast<num_t>(data | get_length<'k'>());

	auto m_len = data | get_length<'j'>();

	// Feature-major traversal: outer loop over j, inner over k.
	// For our chosen layout ('j','k'), this makes the inner loop over the
	// contiguous sample dimension 'k'.
	traverser(data).template for_dims<'j'>([&](auto tj) {
		tj.template for_each<'k'>([&](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			data[state] = static_cast<num_t>(k * j) / static_cast<num_t>(m_len);
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: j x k  (M features, N samples)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: i x k (physically still j x k)
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	const num_t inv_float_n = num_t(1) / float_n;
	const num_t inv_denom   = num_t(1) / (float_n - num_t(1));

	// Cache lengths for tuning the OpenMP regions
	const std::size_t j_len = data | get_length<'j'>();
	const std::size_t i_len = cov  | get_length<'i'>();

#pragma scop

	// 1) mean[j] = (1/n) * sum_k data[k][j]
	{
		// Hoist 'j' so the outer range-based loop iterates features.
		auto mean_data_trav = traverser(mean, data).order(noarr::hoist<'j'>());

		// Each iteration processes one feature j independently.
		#pragma omp parallel for schedule(static) if(j_len >= tuning_t::mean_parallel_threshold)
		for (auto tj : mean_data_trav) {
			// tj has 'j' fixed, 'k' is the remaining dimension.
			mean[tj] = num_t(0);

			// Accumulate over samples k. With layout ('j','k'), this
			// streams through contiguous memory in the 'k' dimension.
			tj.template for_each<'k'>([&](auto state) {
				// state contains both 'j' and 'k'; mean ignores 'k'
				mean[state] += data[state];
			});

			mean[tj] *= inv_float_n;
		}
	}

	// 2) data[k][j] -= mean[j]
	// Traverse again in feature-major order so that samples are contiguous.
	{
		auto data_mean_trav = traverser(data, mean).order(noarr::hoist<'j'>());

		#pragma omp parallel for schedule(static) if(j_len >= tuning_t::center_parallel_threshold)
		for (auto tj : data_mean_trav) {
			// tj has 'j' fixed, we iterate over samples 'k'
			tj.template for_each<'k'>([&](auto state) {
				// mean[state] uses only 'j'
				data[state] -= mean[state];
			});
		}
	}

	// 3) covariance upper triangle and diagonal:
	//    for i in 0..M-1
	//      for j in i..M-1
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//
	// We parallelise across the row index 'i'. Each thread owns a disjoint
	// subset of rows, computes cov[i][j] for j >= i, and never writes to
	// elements owned by another thread.
	{
		auto cov_trav = traverser(cov, data, data_i).order(noarr::hoist<'i'>());

		#pragma omp parallel for schedule(static) if(i_len >= tuning_t::cov_parallel_threshold)
		for (auto ti : cov_trav) {
			auto si    = ti.state();
			auto i_idx = get_index<'i'>(si);

			// Iterate over all columns j, but only keep the upper triangle (j >= i).
			ti.template for_dims<'j'>([&](auto tij) {
				auto s_ij  = tij.state();
				auto j_idx = get_index<'j'>(s_ij);

				// Enforce j >= i (upper triangle including diagonal).
				if (j_idx < i_idx)
					return;

				num_t sum = num_t(0);

				// Accumulate over samples k. Because 'k' is the innermost
				// dimension of both data and data_i, this loop has excellent
				// spatial locality.
				tij.template for_each<'k'>([&](auto sk) {
					// sk contains 'i', 'j', 'k'; each bag uses only the
					// dimensions it cares about:
					//   data  -> 'j', 'k'
					//   data_i-> 'i', 'k'
					sum += data[sk] * data_i[sk];
				});

				cov[s_ij] = sum * inv_denom;
			});
		}
	}

	// 4) Symmetry: cov[j][i] = cov[i][j] for j > i
	//    We fill the strictly lower triangle in a separate pass so that the
	//    main accumulation above remains race-free.
	{
		auto cov_trav_lower = traverser(cov).order(noarr::hoist<'i'>());

		#pragma omp parallel for schedule(static) if(i_len >= tuning_t::cov_parallel_threshold)
		for (auto ti : cov_trav_lower) {
			auto si    = ti.state();
			auto i_idx = get_index<'i'>(si);

			ti.template for_dims<'j'>([&](auto tij) {
				auto s_ij  = tij.state();
				auto j_idx = get_index<'j'>(s_ij);

				// Only strictly lower triangle: j > i
				if (j_idx <= i_idx)
					return;

				auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ji] = cov[s_ij];
			});
		}
	}

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'k'>(n) ^ // samples
		noarr::set_length<'i'>(m) ^ // cov rows
		noarr::set_length<'j'>(m);  // features / cov cols

