			auto s_ki = tki.state();
			auto i_idx = get_index<'i'>(s_ki);

			// Load x_i = data[k][i] once per (k, i) and reuse across all j >= i
			num_t x_i = data_i[s_ki];

			// Now iterate over columns j; skip lower triangle (j < i)
			tki.template for_each<'j'>([=](auto s_kij) {
				auto j_idx = get_index<'j'>(s_kij);
				if (j_idx < i_idx)
					return; // only accumulate upper triangle, including diagonal

				num_t x_j = data[s_kij]; // data[k][j]
				cov[s_kij] += x_i * x_j; // cov[i][j] += data[k][i] * data[k][j]
			});
		});
	});

