	auto m_len = data | get_length<'j'>();

	// Iterate samples in the outer loop and features in the inner loop
	// to write rows of the (k-major, j-minor) layout contiguously.
	traverser(data).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto state) {
			auto [k_idx, j_idx] = get_indices<'k', 'j'>(state);
			data[state] = (num_t)(k_idx * j_idx) / (num_t)m_len;
		});
	});
}

// computation kernel
//
// The implementation follows the mathematical definition:
//
//   mean[j] = (1/n) * sum_k data[k][j]
//
//   data[k][j] <- data[k][j] - mean[j]
//
//   cov[i][j] = sum_k data[k][i] * data[k][j] / (n - 1)
//   cov[j][i] = cov[i][j]
//
// but the loop structure is reorganized to improve data locality:
//
// - Mean:   k-major, j-minor     (stream rows of data)
// - Center: k-major, j-minor     (in-place, row-wise)
// - Cov:    k-major, i-major, j-minor, with reuse of data[k][i]
//           for all j >= i (outer-product style update)
//
// For each (i,j), the sequence of updates over k is still in increasing
// k order, so the roundoff behavior for each covariance entry matches
// the original algorithm (no reassociation of partial sums).
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	const num_t inv_float_n       = (num_t)1.0 / float_n;
	const num_t float_n_minus_one = float_n - (num_t)1.0;

#pragma scop
	// ------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	// ------------------------------------------------------------------

	// 1a) initialize all means to zero
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = (num_t)0;
	});

	// 1b) accumulate over k (samples), streaming data row-wise:
	//     outer loop: k, inner loop: j
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto state) {
			// state has 'k' and 'j'; 'k' is ignored by mean[]
			mean[state] += data[state];
		});
	});

	// 1c) scale by 1/n
	traverser(mean).for_each([&](auto sj) {
		mean[sj] *= inv_float_n;
	});

	// ------------------------------------------------------------------
	// 2) Center the data: data[k][j] -= mean[j]
	//     (k-major, j-minor traversal – row-wise, cache friendly)
	// ------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto state) {
			data[state] -= mean[state]; // mean[state] only uses 'j'
		});
	});

	// ------------------------------------------------------------------
	// 3) Covariance matrix
	//
	// We compute:
	//   cov[i][j] = sum_k data[k][i] * data[k][j] / (n - 1),  for j >= i
	// and then mirror the upper triangle to the lower one.
	//
	// To reduce memory traffic and improve locality:
	//   - we initialize cov to zero once,
	//   - iterate samples k in the outermost loop,
	//   - for each sample k and feature i we load data[k][i] once
	//     and reuse it for all j >= i.
	//
	// For every (i,j), the updates still occur in k order 0..n-1,
	// so numerical behavior per entry is unchanged w.r.t. the
	// original i-j-k loop nest.
	// ------------------------------------------------------------------

	// 3a) initialize full covariance matrix to zero
	traverser(cov).for_each([&](auto s) {
		cov[s] = (num_t)0;
	});

	// 3b) accumulate outer products:
	//     for k in 0..N-1:
	//       for i in 0..M-1:
	//         let x = data[k][i];
	//         for j in i..M-1:
	//           cov[i][j] += x * data[k][j];
	traverser(cov, data, data_i).template for_dims<'k'>([&](auto tk) {
		// tk: 'k' fixed, remaining dims for this traverser are 'i' and 'j'
		tk.template for_dims<'i'>([&](auto tki) {
			// Fixed k and i
			auto s_ki = tki.state();          // contains 'k' and 'i'
			const num_t x_ki = data_i[s_ki];  // data[k][i], loaded once per (k,i)

			// Now sweep j for this (k,i)
			tki.template for_dims<'j'>([&](auto tkij) {
				auto s_kij = tkij.state(); // contains 'k', 'i', 'j'
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_kij);

				// Only update upper triangle (including diagonal)
				if (j_idx < i_idx)
					return;

				// cov only depends on 'i' and 'j'; extra 'k' in s_kij is ignored
				cov[s_kij] += x_ki * data[s_kij]; // data uses 'k' and 'j'; extra 'i' is ignored
			});
		});
	});

