	//     - for j >= i: cov[i][j] /= (n - 1)
	//     - for j < i : cov[i][j]  = cov[j][i]
	traverser(cov).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();                // contains 'i' and 'j'
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

