				auto s_ji = idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ij] = cov[s_ji];
			} else {
				// Upper triangle and diagonal: apply normalization
				cov[s_ij] /= float_n_minus_one;
			}
		});
	});
#pragma endscop
}

